{
  "round": 1,
  "questions": [
    {
      "id": "RQ1",
      "question": "「成本模型」（cost model）在文献中主要指哪几类建模对象与范式？可划分为哪些主要流派（如算法/参数化成本模型、类比与回归模型、数据驱动与机器学习模型、云与服务计算的资源成本/总拥有成本模型）？"
    },
    {
      "id": "RQ2",
      "question": "以 COCOMO 家族、功能点分析为代表的参数化软件成本模型，其核心构成要素（规模度量、成本驱动因子、指数项、校准方式）是什么？后续研究对其做了哪些修正与扩展？"
    },
    {
      "id": "RQ3",
      "question": "数据驱动方法（回归、贝叶斯、机器学习/深度学习）如何用于成本估计与成本预测？相较传统参数化模型，其报告出的精度改进与适用边界是什么？"
    },
    {
      "id": "RQ4",
      "question": "云计算与服务计算场景下的成本模型关注哪些问题（资源定价、虚拟机/容器调度、成本感知的自动伸缩与工作流放置、总拥有成本 TCO）？其建模目标与软件成本估算有何不同？"
    },
    {
      "id": "RQ5",
      "question": "成本模型的质量如何被评估（如 MMRE、PRED(25)、MAE/RMSE、交叉验证与外部效度）？现有研究指出了哪些评估与泛化方面的常见局限？"
    }
  ],
  "queries": [
    {
      "query": "\"cost model\" software cost estimation survey",
      "source": "crossref"
    },
    {
      "query": "COCOMO software cost estimation model calibration",
      "source": "crossref"
    },
    {
      "query": "\"software cost estimation\" machine learning accuracy comparison",
      "source": "crossref"
    },
    {
      "query": "function point analysis effort estimation model",
      "source": "crossref"
    },
    {
      "query": "cloud computing cost model resource pricing optimization",
      "source": "crossref"
    },
    {
      "query": "\"total cost of ownership\" cloud service cost modeling",
      "source": "crossref"
    },
    {
      "query": "all:\"cost model\" AND (all:\"software cost estimation\" OR all:\"effort estimation\")",
      "source": "arxiv"
    },
    {
      "query": "all:\"cost estimation\" AND (all:\"machine learning\" OR all:\"deep learning\") AND all:\"software project\"",
      "source": "arxiv"
    },
    {
      "query": "all:\"cost model\" AND (all:\"cloud\" OR all:\"serverless\" OR all:\"resource allocation\")",
      "source": "arxiv"
    },
    {
      "query": "all:\"cost-aware\" AND (all:\"scheduling\" OR all:\"autoscaling\") AND all:\"cloud\"",
      "source": "arxiv"
    }
  ],
  "inclusion_criteria": [
    "文献须明确提出、构建、校准或评估某种「成本模型」（cost model），包括软件/项目成本与工作量估算模型、云与服务计算的资源成本或总拥有成本模型、以及数据驱动的成本预测模型。",
    "以期刊论文、会议论文、综述（survey/review）或系统性映射研究为主；预印本仅在方法或主题具有代表性且无正式发表版本时纳入。",
    "文献须包含可辨识的模型描述（变量、假设、公式或算法流程）与至少一种评估或应用结果，而非仅讨论成本概念。",
    "语言为英文或中文；发表时间以近 20–25 年为主，但奠基性工作（如 COCOMO 原始文献）不受时间限制，需明确标注其奠基地位。",
    "若为综述类文献，须明确其覆盖范围与检索策略，可作为定位子领域与补充引文的入口。"
  ],
  "exclusion_criteria": [
    "仅在标题或摘要中出现「cost」但实际研究的是成本会计、价格机制、经济政策或临床/医疗费用统计，而非可复用的成本建模方法。",
    "纯粹的行业白皮书、厂商营销材料、博客、新闻稿及无作者与出处信息的网络内容。",
    "无法获取全文或关键模型细节（元数据残缺、仅摘要可得的付费墙文献），除非该文献被多篇纳入文献引为核心参考。",
    "缺乏任何验证、案例或数据支撑的纯立场性评论、社论与观点短文。",
    "与本综述最终收敛范围无关的相邻领域（如电力系统发电成本、交通出行成本）文献，若不能提供可迁移的建模方法则不纳入。"
  ],
  "revision_tasks": [
    "写作前先确认并固定综述口径：「成本模型」歧义较大，本篇应明确以软件/IT 系统与其运行环境（含云与服务计算）的成本与工作量建模为主线，并在引言中用一句话界定边界，说明为何不覆盖医疗、能源等相邻领域，以保持短篇综述的聚焦性。",
    "标题须为真实论文标题（首行以 '# ' 加实际标题），不得使用占位符；标题应体现「成本模型」的具体限定域，避免过宽。",
    "正文结构建议：引言与范围界定 → 成本模型的类型学（参数化/类比/回归/数据驱动/资源成本）→ 各范式的构成要素与代表性方法 → 评估指标与已知局限 → 小结与开放问题。",
    "所有实质论断须有内联引用并对应到 sources 数组中已核验的条目；不得引用未核验或仅凭记忆的文献，也不得虚构 DOI、作者或年份。",
    "严格不要在稿件中撰写或要求 References/参考文献章节：该章节由导出节点依据已核验来源自动生成；只需保证内联引用编号或键与来源列表一致。",
    "区分「请求的范围」与「可获取的证据」：若某子领域（如服务计算成本模型）检索到的可用文献明显不足，应在正文中如实说明证据有限，而非用泛化表述填充。",
    "对跨范式比较（如机器学习模型 vs. COCOMO 的精度对比），须报告其评估指标与数据集差异，避免直接跨数据集比较数值。",
    "摘要与结论中不得宣称「全面覆盖」或「已证明某模型最优」，只陈述已有文献报告的结果与共识程度。",
    "检索若出现某一来源（Crossref 或 arXiv）命中过少或大量噪声，应据实记录并在下一轮调整查询词而非降低纳入标准。"
  ],
  "previous_work": null
}
